/**
 * @fileoverview The wheel's maths, checked exactly against a recording of
 * the colour dialog (picker.js) as it drew and answered in a browser, made
 * while the dialog still had maths of its own; it now draws with wheel.ts's.
 * The recording holds the uniforms each wheel draw was made with (the
 * triangle's hue and corners, the handle's direction and point, the ring's
 * radii) and the colour each press and drag reported, at 1 and 1.5 texels
 * per logical pixel, kept here as literals. The grid's expected terms are
 * the dialog's colour functions of then, evaluated over it, and the ladders'
 * its two branch ladders. A value computed through a sine or a cosine is
 * held within two epsilon of the recording, since the browser's Math.sin and
 * Math.cos may differ from node's in the last place; every other value is
 * exact. The renderer is not run here.
 */
import { describe, expect, it } from 'vitest';
import {
	WHEEL_RING,
	angleOfHue,
	barycentric,
	hueOfAngle,
	ringAt,
	saturatedOf,
	triangleAt,
	triangleColour,
	triangleHandle,
	triangleOf,
	unitOfHue,
	wheelGeometry,
	wheelRegionAt,
	type Corners,
	type Rgb,
	type Vec2,
} from './wheel.ts';

/** A colour the dialog was shown at, and what its draw was made with. */
interface Show {
	ratio: 1 | 1.5;
	colour: number[];
	hue: number[];
	handle: number[];
	corners: number[][];
	handleTri: number[];
}

/**
 * A press on the wheel, or a move of the drag it began, at a point in logical
 * pixels: the colour the dialog was set to before the press, the region the
 * press found (for a move, the region its drag holds), the triangle standing
 * before it, the colour reported, and what the draw it made was made with.
 */
interface Press {
	drag?: true;
	base: number[];
	x: number;
	y: number;
	region: 'ring' | 'triangle' | null;
	hue: number[];
	corners: number[][];
	colour?: number[];
	after?: { hue: number[]; handle: number[]; corners: number[][]; handleTri: number[] };
}

/** The dialog's wheel: 258 logical pixels across. */
const geometryAt = (ratio: number) => wheelGeometry(Math.trunc(258 * ratio), Math.trunc(258 * ratio), 258, ratio);

/** A value with every -0 read as 0: the recording, through JSON, holds no -0. */
const plain = (value: unknown): unknown => (Array.isArray(value) ? value.map(plain) : typeof value === 'number' ? value + 0 : value);

/** Asserts each number within two epsilon of the recording's: values reached through a sine or a cosine. */
const near = (actual: number[] | number[][], expected: number[] | number[][]) => {
	const a = actual.flat(), e = expected.flat();
	expect(a.length).toBe(e.length);
	a.forEach((v, i) => expect(Math.abs(v - e[i])).toBeLessThanOrEqual(2 * Number.EPSILON));
};

