const HUES_AT: [number, number[]][] = [[-180,[0,255,255]],[-179.5,[0,255,253]],[-150,[0,255,127]],[-120,[0,255,0]],[-119.99,[0,255,0]],[-90,[128,255,0]],[-60,[255,255,0]],[-30,[255,127,0]],[-0.001,[255,0,0]],[0,[255,0,0]],[30,[255,0,128]],[59.999,[255,0,255]],[60,[255,0,255]],[90,[127,0,255]],[120,[0,0,255]],[150,[0,128,255]],[179.9,[0,255,255]],[180,[0,256,255]]];

describe('wheelGeometry', () => {
	it('sizes the ring as the dialog drew it, the shaders\' units and radii included', () => {
		for (const ratio of [1, 1.5] as const) {
			const g = geometryAt(ratio);
			expect(g.dim).toBe(258 * ratio);
			expect(g.mid).toEqual([129 * ratio, 129 * ratio]);
			expect(g.outer).toBe(129 * ratio);
			expect(g.inner).toBe((129 - 26) * ratio);
			expect(1 / g.size).toBe(UNIFORMS[ratio].unitT);
			expect(g.ratio / g.dim).toBe(UNIFORMS[ratio].unit);
			expect(g.inner / g.size / g.ratio).toBe(UNIFORMS[ratio].innerRad);
			expect(g.outer / g.size / g.ratio).toBe(UNIFORMS[ratio].outerRad);
		}
	});

	it('takes the ring as a share of the diameter, so a smaller wheel keeps its proportions', () => {
		const g = wheelGeometry(360, 360, 180, 2);
		expect(g.outer - g.inner).toBeCloseTo(180 * 2 * WHEEL_RING, 12);
	});
});

describe('saturatedOf and triangleColour', () => {
	it('read a colour into the wheel\'s terms and back as the dialog did, byte for byte', () => {
		for (const [colour, hue, saturation, intensity, back] of GRID) {
			expect(saturatedOf(colour)).toEqual({ hue, saturation, intensity });
			expect(triangleColour(hue as Rgb, saturation, intensity)).toEqual(back);
		}
	});

	it('read a colour with alpha by its first three channels', () => {
		expect(saturatedOf([200, 100, 50, 0.5])).toEqual(saturatedOf([200, 100, 50]));
	});
});

describe('the hue ladders', () => {
	it('angleOfHue places a saturated colour at its angle, at the sector boundaries and between', () => {
		for (const [hue, degree] of ANGLES) expect(angleOfHue(hue)).toBe(degree);
	});

	it('hueOfAngle gives the colour at an angle, at the sector boundaries and between', () => {
		for (const [degree, hue] of HUES_AT) expect(hueOfAngle(degree)).toEqual(hue);
	});
});

describe('a colour shown on the wheel', () => {
	it('finds the hue, the handle, the triangle and its handle point that the dialog drew', () => {
		for (const show of SHOWS) {
			const g = geometryAt(show.ratio);
			const terms = saturatedOf(show.colour);
			expect(terms.hue).toEqual(show.hue);
			const unit = unitOfHue(terms.hue);
			near([unit[0], -unit[1]], show.handle);
			const corners = triangleOf(unit, g);
			near(corners, show.corners);
			near(triangleHandle(corners, terms.saturation, terms.intensity), show.handleTri);
		}
	});
});

describe('presses and drags on the wheel', () => {
	const run = (ratio: 1 | 1.5, presses: Press[]) => {
		const g = geometryAt(ratio);
		for (const p of presses) {
			const corners = p.corners as Corners;
			if (!p.drag) expect(wheelRegionAt(g, corners, p.x, p.y), `${p.x},${p.y}`).toBe(p.region);
			if (p.region === 'ring') {
				const ring = ringAt(g, p.x, p.y)!;
				const held = saturatedOf(p.base);
				expect(ring.hue).toEqual(p.after!.hue);
				expect(plain([ring.unit[0], -ring.unit[1]])).toEqual(p.after!.handle);
				near(triangleOf(ring.unit, g), p.after!.corners);
				expect(triangleColour(ring.hue, held.saturation, held.intensity)).toEqual(p.colour);
				expect(plain(triangleHandle(p.after!.corners as Corners, held.saturation, held.intensity))).toEqual(p.after!.handleTri);
			} else if (p.region === 'triangle') {
				const terms = triangleAt(g, corners, p.x, p.y);
				expect(terms.saturation).toBeGreaterThanOrEqual(0);
				expect(terms.saturation).toBeLessThanOrEqual(1);
				expect(triangleColour(p.hue as Rgb, terms.saturation, terms.intensity)).toEqual(p.colour);
				expect(plain(triangleHandle(corners, terms.saturation, terms.intensity))).toEqual(p.after!.handleTri);
			}
		}
	};

	it('find the region, set the hue or the tone, and report the colour as the dialog did, at 1 texel per pixel', () => run(1, PRESSES_1));
	it('do the same at 1.5 texels per pixel', () => run(1.5, PRESSES_15));

	it('cover the ring, the triangle, the gap and every edge a triangle drag is clamped onto', () => {
		const g = geometryAt(1);
		const edges = new Set<number>();
		for (const p of PRESSES_1.filter((p) => p.drag && p.region === 'triangle')) {
			const q: Vec2 = [(p.x - 129) / 258, -((p.y - 129) / 258)];
			const b = barycentric(q, ...(p.corners as Corners));
			edges.add(b[0] < 0 ? 0 : b[1] < 0 ? 1 : b[2] < 0 ? 2 : -1);
		}
		expect([...edges].sort()).toEqual([-1, 0, 1, 2]);
		expect(new Set(PRESSES_1.filter((p) => !p.drag).map((p) => p.region))).toEqual(new Set(['ring', 'triangle', null]));
		expect(ringAt(g, 129, 129)).toBeNull();
	});

	it('take the ring\'s leftmost point at 180 degrees, its hue\'s green channel past a byte', () => {
		const ring = ringAt(geometryAt(1), 1, 129)!;
		expect(ring.hue).toEqual([0, 256, 255]);
		expect(triangleColour(ring.hue, 1, 0.5)).toEqual([0, 255, 255]);
	});
});

describe('barycentric', () => {
	it('weighs the corners themselves and the centre', () => {
		const a: Vec2 = [0, 0], b: Vec2 = [1, 0], c: Vec2 = [0, 1];
		expect(barycentric(a, a, b, c)).toEqual([1, 0, 0]);
		expect(barycentric(b, a, b, c)).toEqual([0, 1, 0]);
		expect(barycentric(c, a, b, c)).toEqual([0, 0, 1]);
		const m = barycentric([1 / 3, 1 / 3], a, b, c);
		for (const w of m) expect(w).toBeCloseTo(1 / 3, 12);
	});
});
